from schemathesis.core.errors import InvalidSchema

# Adapted from http.client._is_illegal_header_value
INVALID_HEADER_RE = re.compile(r"\n(?![ \t])|\r(?![ \t\n])")
# RFC 9110 Section 5.5: invalid field value chars are 0x00-0x08, 0x0A-0x1F, 0x7F
_RFC9110_INVALID_HEADER_VALUE_RE = re.compile(r"[\x00-\x08\x0a-\x1f\x7f]")


def has_invalid_characters(name: str, value: object) -> bool:
    from requests.exceptions import InvalidHeader
    from requests.utils import check_header_validity

    if not isinstance(value, str):
        return False
    try:
        check_header_validity((name, value))
        return bool(INVALID_HEADER_RE.search(value)) or bool(_RFC9110_INVALID_HEADER_VALUE_RE.search(value))
    except InvalidHeader:
        return True


def has_leading_whitespace(value: str) -> bool:
    """Whether the value opens with a whitespace character."""
    return value[:1].strip() != value[:1]


def is_latin_1_encodable(value: object) -> TypeGuard[str]:
    """Check if a value is a Latin-1 encodable string."""
    if not isinstance(value, str):
        return False
    try:
        value.encode("latin-1")
        return True
    except UnicodeEncodeError:
        return False


def check_header_name(name: str) -> None:
    from requests.exceptions import InvalidHeader
    from requests.utils import check_header_validity

    if not name:
        raise InvalidSchema("Header name should not be empty")
    if not name.isascii():
        # `urllib3` encodes header names to ASCII
        raise InvalidSchema(f"Header name should be ASCII: {name}")
    try:
        check_header_validity((name, ""))
    except InvalidHeader as exc:
        raise InvalidSchema(str(exc)) from None
    if bool(INVALID_HEADER_RE.search(name)):
        raise InvalidSchema(f"Invalid header name: {name}")


SURROGATE_PAIR_RE = re.compile(r"[\ud800-\udfff]")
_contains_surrogate_pair = SURROGATE_PAIR_RE.search


def contains_unicode_surrogate_pair(item: object) -> TypeGuard[list[Any] | str]:
    if isinstance(item, list):
        return any(isinstance(item_, str) and bool(_contains_surrogate_pair(item_)) for item_ in item)
    return isinstance(item, str) and bool(_contains_surrogate_pair(item))


INVALID_BASE_URL_MESSAGE = (
    "The provided base URL is invalid. This URL serves as a prefix for all API endpoints you want to test. "
    "Make sure it is a properly formatted URL."
)


def validate_base_url(value: str) -> None:
    try:
        netloc = urlparse(value).netloc
    except ValueError as exc:
        raise ValueError(INVALID_BASE_URL_MESSAGE) from exc
    if value and not netloc:
        raise ValueError(INVALID_BASE_URL_MESSAGE)


INVALID_ORIGIN_MESSAGE = (
    "The provided origin is invalid. It must contain only the scheme, host and port, as the path comes "
    "from the schema. Use the base URL option if you want to set the path yourself."
)


def validate_origin(value: str) -> None:
    try:
        parsed = urlparse(value)
    except ValueError as exc:
        raise ValueError(INVALID_ORIGIN_MESSAGE) from exc
    if not parsed.netloc or parsed.path.strip("/") or parsed.query or parsed.fragment:
        raise ValueError(INVALID_ORIGIN_MESSAGE)

